INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7005,8005,'github-estudo-estado-repositorio','Init, clone, status e diff','{"introduction":"Estude working tree, staging area, repositório, arquivos rastreados e comparação de mudanças antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Init, clone, status e diff cobre working tree, staging area, repositório, arquivos rastreados e comparação de mudanças. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git status --short\ngit diff\ngit diff --staged","keyPoints":["working tree, staging area, repositório, arquivos rastreados e comparação de mudanças","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Iniciar repositório","2. Ver estado resumido","3. Revisar mudanças locais","4. Revisar staging","5. Diagnóstico completo"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Init, clone, status e diff","url":"https://docs.github.com/pt/get-started/git-basics/about-git"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',32,9021,9022,1,'published');
