INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7007,8007,'github-estudo-desfazer-recuperar','Restore, reset, revert e reflog','{"introduction":"Estude desfazer sem perder trabalho, retirar do staging, reverter histórico público e recuperar referências antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Restore, reset, revert e reflog cobre desfazer sem perder trabalho, retirar do staging, reverter histórico público e recuperar referências. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git restore --staged arquivo.js\ngit revert HEAD\ngit reflog","keyPoints":["desfazer sem perder trabalho, retirar do staging, reverter histórico público e recuperar referências","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Descartar alteração local","2. Retirar do staging","3. Reverter commit publicado","4. Localizar referência perdida","5. Recuperar commit com segurança"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Restore, reset, revert e reflog","url":"https://docs.github.com/pt/get-started/using-git/dealing-with-non-fast-forward-errors"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',32,9031,9032,13,'published');
--> statement-breakpoint
