INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7008,8008,'github-estudo-arquivos-especiais','.gitignore, atributos e Git LFS','{"introduction":"Estude padrões de exclusão, arquivos já rastreados, normalização de linha, linguist e arquivos grandes antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":".gitignore, atributos e Git LFS cobre padrões de exclusão, arquivos já rastreados, normalização de linha, linguist e arquivos grandes. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"node_modules/\n.env\ndist/\n*.log","keyPoints":["padrões de exclusão, arquivos já rastreados, normalização de linha, linguist e arquivos grandes","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Ignorar artefatos","2. Proteger segredos locais","3. Remover arquivo do índice","4. Normalizar finais de linha","5. Rastrear binários grandes"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":".gitignore, atributos e Git LFS","url":"https://docs.github.com/pt/repositories/working-with-files/managing-large-files/about-large-files-on-github"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',32,9036,9037,19,'published');
