INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7009,8009,'github-estudo-branches-switch','Branches e git switch','{"introduction":"Estude criação, troca, listagem, renomeação, exclusão e convenções de nomes antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Branches e git switch cobre criação, troca, listagem, renomeação, exclusão e convenções de nomes. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git switch -c feat/login\ngit branch --show-current","keyPoints":["criação, troca, listagem, renomeação, exclusão e convenções de nomes","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Criar branch de feature","2. Listar branches","3. Confirmar branch atual","4. Renomear branch","5. Encerrar branch integrada"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Branches e git switch","url":"https://docs.github.com/pt/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/about-branches"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',33,9042,9043,1,'published');
