INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7011,8011,'github-estudo-rebase-cherry-pick','Rebase e cherry-pick','{"introduction":"Estude reaplicar commits, histórico linear, rebase interativo, continuar/abortar e transportar correções antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Rebase e cherry-pick cobre reaplicar commits, histórico linear, rebase interativo, continuar/abortar e transportar correções. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git switch feat/login\ngit rebase main","keyPoints":["reaplicar commits, histórico linear, rebase interativo, continuar/abortar e transportar correções","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Atualizar feature linearmente","2. Continuar rebase resolvido","3. Abortar rebase","4. Reorganizar commits locais","5. Transportar hotfix"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Rebase e cherry-pick","url":"https://docs.github.com/pt/get-started/using-git/about-git-rebase"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',33,9052,9053,13,'published');
