INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7013,8013,'github-estudo-remotos-sincronizacao','Remotes, fetch, pull e push','{"introduction":"Estude origin, rastreamento, fetch, pull com rebase, push, upstream e divergência antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Remotes, fetch, pull e push cobre origin, rastreamento, fetch, pull com rebase, push, upstream e divergência. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git remote -v\ngit fetch origin\ngit pull --rebase origin main","keyPoints":["origin, rastreamento, fetch, pull com rebase, push, upstream e divergência","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Adicionar origin","2. Inspecionar remotos","3. Buscar sem integrar","4. Atualizar com rebase","5. Publicar e rastrear branch"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Remotes, fetch, pull e push","url":"https://docs.github.com/pt/get-started/git-basics/managing-remote-repositories"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',34,9063,9064,1,'published');
