INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7014,8014,'github-estudo-fork-upstream','Forks e upstream','{"introduction":"Estude fork, clone, remote upstream, sincronização, contribuição externa e atualização do fork antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Forks e upstream cobre fork, clone, remote upstream, sincronização, contribuição externa e atualização do fork. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"gh repo fork org/projeto --clone\ngit remote add upstream https://github.com/org/projeto.git","keyPoints":["fork, clone, remote upstream, sincronização, contribuição externa e atualização do fork","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Criar e clonar fork","2. Adicionar upstream","3. Buscar projeto original","4. Sincronizar main","5. Preparar contribuição"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Forks e upstream","url":"https://docs.github.com/pt/pull-requests/collaborating-with-pull-requests/working-with-forks/about-permissions-and-visibility-of-forks"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',34,9068,9069,7,'published');
