INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7021,8021,'github-estudo-seguranca-codigo','Dependabot e segurança de código','{"introduction":"Estude Dependabot, secret scanning, code scanning, alertas, políticas e atualização segura antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Dependabot e segurança de código cobre Dependabot, secret scanning, code scanning, alertas, políticas e atualização segura. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"version: 2\nupdates:\n  - package-ecosystem: npm\n    directory: /\n    schedule:\n      interval: weekly","keyPoints":["Dependabot, secret scanning, code scanning, alertas, políticas e atualização segura","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Atualizações semanais","2. CodeQL para JavaScript","3. Analisar com CodeQL","4. Tratar segredo exposto","5. Resposta a vulnerabilidade"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Dependabot e segurança de código","url":"https://docs.github.com/pt/code-security"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',36,9105,9106,1,'published');
--> statement-breakpoint
