INSERT OR IGNORE INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (7024,8024,'github-estudo-git-avancado','Git avançado e manutenção','{"introduction":"Estude worktree, submodules, bisect, blame, reflog, gc, fsck, assinatura e diagnóstico antes de iniciar as cinco batalhas deste bloco.","sections":[{"title":"Conceitos centrais","text":"Git avançado e manutenção cobre worktree, submodules, bisect, blame, reflog, gc, fsck, assinatura e diagnóstico. Aprenda a intenção de cada comando ou configuração antes de executá-lo em um projeto real."},{"title":"Prática segura","text":"Use repositórios de treino, revise o estado antes de alterar o histórico e nunca cole tokens, chaves privadas ou segredos no editor ou em commits."},{"title":"Aplicação profissional","text":"As batalhas avançam de uma ação isolada para sequências reproduzíveis, revisão, automação e diagnóstico de situações reais."}],"exampleCode":"git bisect start\ngit bisect bad HEAD\ngit bisect good v1.0.0","keyPoints":["worktree, submodules, bisect, blame, reflog, gc, fsck, assinatura e diagnóstico","Comandos previsíveis e reversíveis","Segredos nunca entram no repositório","Revisão do estado antes de publicar"],"practiceObjectives":["1. Abrir trabalho paralelo","2. Adicionar submódulo","3. Iniciar busca binária","4. Investigar linha e arquivo","5. Auditoria final do repositório"],"pdfUrl":"/materials/github/github-guia-completo.pdf","videoUrl":"https://skills.github.com/","videoLabel":"Laboratório oficial GitHub Skills","references":[{"label":"Git avançado e manutenção","url":"https://git-scm.com/docs"},{"label":"Documentação oficial do GitHub","url":"https://docs.github.com/pt"}]}',36,9120,9121,19,'published');
